void sig_handler_quit(int sig) {
  int freed_conn = 0;
  fflush(stdout);
  if(logger)
    logger->vtbl->deinit();

  freed_conn = destroy_all_conn();
  if(freed_conn && !(NET_print_flags & NET_PRINT_JSON))
    fprintf(stderr, "Cleaned %d remaining connection(s) from connection pool\n",
            freed_conn);

  network_handler_destroy(mod, &n);

  if(p)
    pcap_close(p);
  if(interface_name)
    free(interface_name);
  if(filter)
    free(filter);
  if(file)
    free(file);

  exit(sig);
}

void sig_handler_usr(int sig) {
  int freed_conn = 0;

  if(sig == SIGUSR1) {
    if(!first_conn) {
      fprintf(stderr,
              "Received SIGUSR1, connection pool empty, nothing to list.\n");
    } else {
      fprintf(
          stderr,
          "Received SIGUSR1, listing currently tracked connection(s) ...\n");
      list_all_conn();
    }
  } else if(sig == SIGUSR2) {
    if(!first_conn) {
      fprintf(stderr,
              "Received SIGUSR2, connection pool empty, nothing to purge.\n");
    } else {
      fprintf(stderr, "Received SIGUSR2, purging connection pool ...\n");
      freed_conn = destroy_all_conn();
      if(freed_conn && !(NET_print_flags & NET_PRINT_JSON))
        fprintf(stderr, "Purged %d connection(s) from connection pool\n",
                freed_conn);
    }
  }
}

void pcap_cb(u_char *ptr, const struct pcap_pkthdr *hdr, const u_char *data) {
  n_handler *n;
  int len;
  struct ether_header *e_hdr = (struct ether_header *)data;
  int type = ETHERTYPE_IP;
  int cleaned_conn;

  n = (n_handler *)ptr;
  if(hdr->caplen != hdr->len)
    err_exit("Length mismatch", -1);

  len = hdr->len;

  switch(pcap_if_type) {
    case DLT_RAW:
      switch(((u_int8_t)*data) >> 4) {
        case 4:
          type = ETHERTYPE_IP;
          break;
        case 6:
          type = ETHERTYPE_IPV6;
          break;
        default:
          fprintf(stderr, "Unknown packet type, skipping ...\n");
          return;
      }
      break;
#ifdef DLT_LOOP
    case DLT_LOOP:
#endif
    case DLT_NULL:
      data += 4;
      len -= 4;
      break;
    case DLT_EN10MB:
      if(len < sizeof(struct ether_header)) {
        if(!(NET_print_flags & NET_PRINT_JSON))
          fprintf(stderr,
                  "Frame size too small to contain Ethernet header, skipping "
                  "...\n");
        return;
      }

      type = ntohs(e_hdr->ether_type);

      data += sizeof(struct ether_header);
      len -= sizeof(struct ether_header);

      /* if vlans, push past VLAN header (4 bytes) */
      if(type == ETHERTYPE_8021Q) {
        type = ntohs(*(u_int16_t *)(data + 2));

        data += 4;
        len += 4;
      }

      if(type != ETHERTYPE_IP && type != ETHERTYPE_IPV6)
        return;

      break;
    case DLT_IEEE802:
      data += 22;
      len -= 22;
      break;
    case DLT_FDDI:
      data += 21;
      len -= 21;
      break;
#ifdef __amigaos__
    case DLT_MIAMI:
      data += 16;
      len -= 16;
      break;
#endif
    case DLT_SLIP:
#ifdef DLT_SLIP_BSDOS
    case DLT_SLIP_BSDOS:
#endif
#if defined(__FreeBSD__) || defined(__OpenBSD__) || defined(__NetBSD__) || \
    defined(__bsdi__) || defined(__APPLE__)
      data += 16;
      len -= 16;
#else
      data += 24;
      len -= 24;
#endif
      break;
    case DLT_PPP:
#ifdef DLT_PPP_BSDOS
    case DLT_PPP_BSDOS:
#endif
#ifdef DLT_PPP_SERIAL
    case DLT_PPP_SERIAL:
#endif
#ifdef DLT_PPP_ETHER
    case DLT_PPP_ETHER:
#endif
#if defined(__FreeBSD__) || defined(__OpenBSD__) || defined(__NetBSD__) || \
    defined(__bsdi__) || defined(__APPLE__)
      data += 4;
      len -= 4;
#else
#if defined(sun) || defined(__sun)
      data += 8;
      len -= 8;
#else
      data += 24;
      len -= 24;

