  } else {
    /* First decrypt*/
    EVP_Cipher(d->evp, out, in, inl);

    CRDUMP("Plaintext", out, inl);
    *outl = inl;

    /* Now strip off the padding*/
    if(d->cs->block > 1) {
      pad = out[inl - 1];
      *outl -= (pad + 1);
    }

    /* And the MAC */
    *outl -= d->cs->dig_len;
    mac = out + (*outl);
    CRDUMP("Record data", out, *outl);

    /* Now check the MAC */
    if(ssl->version == 0x300) {
      if((r = ssl3_check_mac(d, ct, version, out, *outl, mac)))
