       * non-stream ciphers. */
      if(ssl->version >= 0x0302 && ssl->cs->block > 1) {
        UINT4 blk = ssl->cs->block;
        if(blk <= *outl) {
          *outl -= blk;
          memmove(out, out + blk, *outl);
        } else {
          DBG((0, "Block size greater than Plaintext!"));
          ERETURN(SSL_BAD_MAC);
        }
      }
      if((r = tls_check_mac(d, ct, version, out, *outl, NULL, 0, mac)))
        ERETURN(r);
    }
