int ssl_decode_switch(ssl_obj *ssl,
                      decoder *dtable,
                      int value,
                      int dir,
                      segment *seg,
                      Data *data) {
  while(dtable && dtable->type != -1 && dtable->name != NULL) {
    if(dtable->type == value) {
      INDENT_INCR;
      explain(ssl, "%s", dtable->name);
      if(dtable->print) {
        INDENT_INCR;
        dtable->print(ssl, dir, seg, data);
        INDENT_POP;
      }
      INDENT_POP;
      return 0;
    }
    dtable++;
  }

  ERETURN(R_NOT_FOUND);
}

