int ssl_decode_uintX(ssl_obj *ssl,
                     char *name,
                     int size,
                     UINT4 p,
                     Data *data,
                     UINT4 *x) {
  UINT4 v = 0;
  UINT4 _x;

  if(!x)
    x = &_x;

  if(size > data->len) {
    fprintf(stderr, "Short read: %d bytes available (expecting %d)\n",
            data->len, size);
    ERETURN(R_EOD);
  }

  while(size--) {
    v <<= 8;
    v |= *(data->data)++;
    data->len--;
  }

  P_(p) { explain(ssl, "%s = %d\n", name, *x); }
  *x = v;
  return 0;
}

int ssl_decode_opaque_array(ssl_obj *ssl,
                            char *name,
                            int size,
                            UINT4 p,
                            Data *data,
                            Data *x) {
  UINT4 len;
  char n[1000];
  int r;
  Data _x;

  if(!x)
    x = &_x;

  sprintf(n, "%s (length)", name ? name : "<unknown>");
  if(size < 0) {
    size *= -1;
    if((r = ssl_decode_uintX(ssl, n, BYTES_NEEDED(size), P_DC, data, &len)))
      ERETURN(r);
  } else {
    len = size;
  }

  if(len > data->len) {
    fprintf(stderr, "Not enough data. Found %d bytes (expecting %d)\n",
            data->len, size);
    ERETURN(R_EOD);
  }

  x->data = data->data;
  x->len = len;
  data->data += len;
  data->len -= len;

  P_(p) { exdump(ssl, name, x); }
